-- NeetCode 150: the fixed list of problems you work through.
-- Source: NeetCode's own problem data (github.com/neetcode-gh/leetcode, .problemSiteData.json),
-- entries flagged "neetcode150", in NeetCode roadmap order. Links go to LeetCode.

CREATE TABLE catalog_problems (
    id              SMALLINT     PRIMARY KEY,          -- 1..150, roadmap order
    category        VARCHAR(40)  NOT NULL,
    category_order  SMALLINT     NOT NULL,             -- 1 = Arrays & Hashing ... 18 = Bit Manipulation
    name            VARCHAR(200) NOT NULL,
    difficulty      VARCHAR(6)   NOT NULL CHECK (difficulty IN ('EASY', 'MEDIUM', 'HARD')),
    url             VARCHAR(500) NOT NULL
);
CREATE UNIQUE INDEX catalog_problems_name_unique ON catalog_problems (lower(name));


-- Each catalog problem can be marked done at most once.
ALTER TABLE problems ADD COLUMN catalog_id SMALLINT REFERENCES catalog_problems (id);
CREATE UNIQUE INDEX problems_catalog_unique ON problems (catalog_id) WHERE catalog_id IS NOT NULL;

-- Link problems you logged by hand earlier when the name matches a NeetCode problem.
-- Anything that doesn't match keeps catalog_id = NULL and shows as an "earlier entry".
UPDATE problems p
SET catalog_id = c.id
FROM catalog_problems c
WHERE lower(p.name) = lower(c.name);

-- "Method used" becomes "What did you learn?".
ALTER TABLE problems RENAME COLUMN method TO learnings;
ALTER TABLE problems RENAME CONSTRAINT problems_method_not_blank TO problems_learnings_not_blank;

-- The "solved it yourself?" question is gone; old answers are kept.
ALTER TABLE problems ALTER COLUMN solved_myself DROP NOT NULL;

-- Optional link to your Excalidraw drawing for the problem.
ALTER TABLE problems ADD COLUMN excalidraw_url VARCHAR(500);
